CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS case_types(id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS case_type_docs(id SERIAL PRIMARY KEY, case_type_id INT NOT NULL REFERENCES case_types(id) ON DELETE CASCADE, name TEXT NOT NULL, position INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS clients(id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, phone TEXT, email TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE SEQUENCE IF NOT EXISTS case_code_seq START 1001;
CREATE TABLE IF NOT EXISTS cases(id SERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, client_id INT NOT NULL REFERENCES clients(id), case_type_id INT NOT NULL REFERENCES case_types(id), status TEXT NOT NULL DEFAULT 'new', assignee_id INT REFERENCES users(id), due DATE, rounds INT NOT NULL DEFAULT 0, note TEXT, created_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS case_docs(id SERIAL PRIMARY KEY, case_id INT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, name TEXT NOT NULL, done BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS files(id SERIAL PRIMARY KEY, client_id INT REFERENCES clients(id) ON DELETE CASCADE, case_id INT REFERENCES cases(id) ON DELETE CASCADE, case_doc_id INT REFERENCES case_docs(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime TEXT, size INT NOT NULL, data BYTEA NOT NULL, uploaded_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS comments(id SERIAL PRIMARY KEY, case_id INT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, user_id INT REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS activity(id SERIAL PRIMARY KEY, case_id INT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, user_id INT REFERENCES users(id), text TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS credentials(id SERIAL PRIMARY KEY, client_id INT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, label TEXT NOT NULL, username TEXT, secret_enc TEXT NOT NULL, created_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS credential_access(id SERIAL PRIMARY KEY, credential_id INT NOT NULL REFERENCES credentials(id) ON DELETE CASCADE, user_id INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_cases_status ON cases(status);
CREATE INDEX IF NOT EXISTS idx_files_case ON files(case_id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS wa_opt_in BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE files ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE files ADD COLUMN IF NOT EXISTS sender_phone TEXT;
ALTER TABLE files ADD COLUMN IF NOT EXISTS sender_name TEXT;
ALTER TABLE files ADD COLUMN IF NOT EXISTS note TEXT;
ALTER TABLE files ADD COLUMN IF NOT EXISTS inbox BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE files ADD COLUMN IF NOT EXISTS path TEXT;
ALTER TABLE files ALTER COLUMN data DROP NOT NULL;
CREATE INDEX IF NOT EXISTS idx_files_inbox ON files(inbox) WHERE inbox;
CREATE TABLE IF NOT EXISTS wa_messages(id TEXT PRIMARY KEY, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS wa_log(id SERIAL PRIMARY KEY, user_id INT, to_phone TEXT, template TEXT, ok BOOLEAN, error TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS kv(key TEXT PRIMARY KEY, value TEXT);
ALTER TABLE cases ADD COLUMN IF NOT EXISTS completed_at TIMESTAMPTZ;
ALTER TABLE cases ADD COLUMN IF NOT EXISTS submitted_at TIMESTAMPTZ;
UPDATE cases c SET completed_at=(SELECT max(a.created_at) FROM activity a WHERE a.case_id=c.id AND a.text LIKE '%→ done') WHERE c.status='done' AND c.completed_at IS NULL;
UPDATE cases c SET submitted_at=(SELECT min(a.created_at) FROM activity a WHERE a.case_id=c.id AND a.text LIKE '%→ submitted') WHERE c.submitted_at IS NULL AND c.status IN ('submitted','returned','done');
ALTER TABLE users ADD COLUMN IF NOT EXISTS seen_guide BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar BYTEA;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_mime TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_at TIMESTAMPTZ;
ALTER TABLE case_types ADD COLUMN IF NOT EXISTS sop TEXT;
CREATE TABLE IF NOT EXISTS role_playbook(role TEXT PRIMARY KEY, summary TEXT NOT NULL DEFAULT '', duties JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS stage_playbook(stage TEXT PRIMARY KEY, owner_roles JSONB NOT NULL DEFAULT '[]', steps JSONB NOT NULL DEFAULT '[]', done_when TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS case_steps(case_id INT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, stage TEXT NOT NULL, idx INT NOT NULL, by_user INT REFERENCES users(id), at TIMESTAMPTZ DEFAULT now(), PRIMARY KEY(case_id,stage,idx));
ALTER TABLE comments ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
ALTER TABLE cases ADD COLUMN IF NOT EXISTS escalated_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS audit_log(id SERIAL PRIMARY KEY, user_id INT, actor_name TEXT, action TEXT NOT NULL, details TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(key TEXT PRIMARY KEY, name TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'STAFF', team_queue BOOLEAN NOT NULL DEFAULT FALSE, summary TEXT NOT NULL DEFAULT '', duties JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS notifs(id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, case_id INT REFERENCES cases(id) ON DELETE CASCADE, body TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_notifs_user ON notifs(user_id);
CREATE TABLE IF NOT EXISTS auth_sessions(id UUID PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, last_activity TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_auth_sessions_activity ON auth_sessions(last_activity);
CREATE TABLE IF NOT EXISTS lock_screen_content(day DATE PRIMARY KEY, theme TEXT NOT NULL, image_category TEXT NOT NULL, quote_category TEXT NOT NULL, image_data BYTEA NOT NULL, image_mime TEXT NOT NULL, image_credit TEXT NOT NULL, image_page_url TEXT NOT NULL, quotes JSONB NOT NULL CHECK(jsonb_array_length(quotes)=3), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE cases ADD COLUMN IF NOT EXISTS track_number TEXT;
ALTER TABLE clients ADD COLUMN IF NOT EXISTS track_number TEXT;
CREATE INDEX IF NOT EXISTS idx_cases_track ON cases(track_number) WHERE track_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_cases_client ON cases(client_id);
CREATE INDEX IF NOT EXISTS idx_cases_assignee ON cases(assignee_id);
CREATE INDEX IF NOT EXISTS idx_comments_case ON comments(case_id);
CREATE INDEX IF NOT EXISTS idx_activity_case ON activity(case_id);
CREATE INDEX IF NOT EXISTS idx_files_client ON files(client_id);
CREATE INDEX IF NOT EXISTS idx_credentials_client ON credentials(client_id);
CREATE INDEX IF NOT EXISTS idx_credential_access_cred ON credential_access(credential_id);
